const harness="'use strict';\nconst fs=require('node:fs'),vm=require('node:vm'),assert=require('node:assert/strict');\nconst {createRequire}=require('node:module'),{pathToFileURL}=require('node:url');\nconst fetch=(url,options={})=>globalThis.fetch(url,{...options,signal:AbortSignal.timeout(5000)});\nasync function main(){\n const [directory,dependencyRoot]=process.argv.slice(2);\n const requireDependency=createRequire(dependencyRoot+'/package.json');\n const resolved=fs.realpathSync(requireDependency.resolve('express'));\n assert(resolved.startsWith(fs.realpathSync(dependencyRoot+'/node_modules')+'/'));\n const express=requireDependency('express');\n const {createStartupReadiness}=await import(pathToFileURL(directory+'/startupReadiness.mjs'));\n const baseline=fs.readFileSync(directory+'/app.before.mjs','utf8');\n const candidate=fs.readFileSync(directory+'/app.after.mjs','utf8');\n const controls=[],results=[];\n async function withServer(app,fn){const server=app.listen(0,'127.0.0.1');await new Promise((resolve,reject)=>{server.once('listening',resolve);server.once('error',reject);});try{await fn('http://127.0.0.1:'+server.address().port);}finally{server.closeAllConnections?.();await new Promise(resolve=>server.close(resolve));}}\n async function test(name,fn){try{await fn();results.push({name,pass:true});}catch(e){results.push({name,pass:false,error:e.message});}}\n const start=baseline.indexOf('app.use((req, res, next) => {',baseline.indexOf('// Phase 113EK:'));\n const end=baseline.indexOf('\\n});',start)+4;assert(start>0&&end>start);\n const readyStart=baseline.indexOf('app.get(\"/readyz\",');const readyEnd=baseline.indexOf('\\n});',readyStart)+4;\n const oldApp=express();vm.runInNewContext(baseline.slice(start,end)+'\\n'+baseline.slice(readyStart,readyEnd),{app:oldApp});\n await withServer(oldApp,async url=>{for(const route of ['/ready','/api/ready','/readyz']){const r=await fetch(url+route);assert.equal(r.status,200);}});\n controls.push({name:'baseline_readiness_returns_200_without_schema_completion',pass:true});\n await test('application_wiring_precedes_legacy_aliases',async()=>{\n  assert(candidate.includes('import { createStartupReadiness } from \"./startupReadiness.mjs\";'));\n  assert(candidate.indexOf('app.use(startupReadiness.middleware);')<candidate.indexOf('// Phase 113EK:'));\n  assert(candidate.includes('schemaBootstrap: ensureSchema, getBillingState: () => billingRuntime.status().state'));\n  assert(candidate.includes('startupReadiness.start().catch('));\n  assert(candidate.includes('function shutdown(signal) {\\n  startupReadiness.stop();'));\n  assert(!candidate.includes('ensureSchema().catch('));\n });\n let settle,invocations=0,billing='disabled';\n const readiness=createStartupReadiness({schemaBootstrap:()=>{invocations++;return new Promise(resolve=>{settle=resolve;});},getBillingState:()=>billing});\n const app=express();app.use(readiness.middleware);app.get('/healthz',(_q,r)=>r.status(200).json({ok:true}));app.use((_q,r)=>r.status(404).end());\n await withServer(app,async url=>{\n  for(const route of ['/ready','/readyz','/api/ready','/api/readyz','/READY/'])await test('pending_'+route,async()=>{const r=await fetch(url+route);assert.equal(r.status,503);assert.equal(r.headers.get('cache-control'),'no-store');assert.equal((await r.json()).ok,false);});\n  await test('pending_HEAD_no_body',async()=>{const r=await fetch(url+'/readyz',{method:'HEAD'});assert.equal(r.status,503);assert.equal(await r.text(),'');});\n  await test('liveness_unaffected',async()=>assert.equal((await fetch(url+'/healthz')).status,200));\n  await test('POST_not_intercepted',async()=>assert.equal((await fetch(url+'/ready',{method:'POST'})).status,404));\n  const pending=readiness.start();await Promise.resolve();\n  await test('inflight_single_bootstrap',async()=>{assert.strictEqual(readiness.start(),pending);assert.equal(invocations,1);assert.equal((await fetch(url+'/ready')).status,503);});\n  settle({ok:true});await pending;\n  await test('successful_schema_ready',async()=>{const r=await fetch(url+'/readyz');assert.equal(r.status,200);assert.deepEqual(await r.json(),{ok:true,status:'ready'});});\n  await test('billing_failure_blocks_readiness',async()=>{billing='failed';assert.equal((await fetch(url+'/ready')).status,503);billing='ready';assert.equal((await fetch(url+'/ready')).status,200);});\n  readiness.stop();\n  await test('shutdown_blocks_readiness',async()=>{assert.equal((await fetch(url+'/ready')).status,503);await readiness.start();assert.equal(invocations,1);});\n });\n for(const [name,bootstrap]of [['failed_result',async()=>({ok:false,secret:'private-marker'})],['rejected_bootstrap',async()=>{throw Error('private-marker');}],['malformed_result',async()=>undefined]])await test(name,async()=>{const r=createStartupReadiness({schemaBootstrap:bootstrap});await r.start();assert.deepEqual(r.status(),{ok:false,status:'not_ready'});assert(!JSON.stringify(r.status()).includes('private-marker'));});\n await test('late_success_cannot_reverse_shutdown',async()=>{let resolve;const r=createStartupReadiness({schemaBootstrap:()=>new Promise(x=>{resolve=x;})});const p=r.start();await Promise.resolve();r.stop();resolve({ok:true});await p;assert.equal(r.status().ok,false);});\n await test('billing_status_error_fails_closed',async()=>{const r=createStartupReadiness({schemaBootstrap:async()=>({ok:true}),getBillingState:()=>{throw Error('private-marker');}});await r.start();assert.equal(r.status().ok,false);});\n\n const schemaContext=vm.createContext({structuredClone});\n const schemaModule=new vm.SourceTextModule(fs.readFileSync(directory+'/ensureSchema.applied.mjs','utf8'),{context:schemaContext,initializeImportMeta(meta){meta.url='file:///synthetic/server/db/ensureSchema.mjs';}});\n await schemaModule.link(spec=>{\n  const values=spec==='drizzle-orm'?{sql:{raw:x=>x}}:spec==='./connection.mjs'?{db:{execute(){throw Error('Unexpected real DB');}}}:spec==='../utils/logger.mjs'?{logger:{}}:spec==='node