const inputs=new Map(),missing=new Set();let directory,before,status='STOPPED',result;
function read(file){
 const s=fs.lstatSync(file);check(s.isFile()&&s.size<=4194304&&fs.realpathSync(file)===file,'Unsafe input: '+file);
 const b=fs.readFileSync(file),h=hash(b);if(inputs.has(file))check(inputs.get(file)===h,'Input changed: '+file);else inputs.set(file,h);return b;
}
function absent(file){try{fs.lstatSync(file);throw Error('Expected absent path: '+file);}catch(e){if(e.code!=='ENOENT')throw e;}missing.add(file);}
function git(...args){const r=spawnSync('git',['--no-pager','--no-optional-locks','-c','core.fsmonitor=false','-c','core.quotePath=true',...args],{cwd:ROOT,env,encoding:'utf8',timeout:30000,maxBuffer:33554432});check(!r.error&&r.status===0,'Git inspection failed: '+args[0]);return r.stdout;}
function state(){return JSON.stringify({head:git('rev-parse','HEAD').trim(),branch:git('branch','--show-current').trim(),index:hash(read(path.resolve(ROOT,git('rev-parse','--git-path','index').trim()))),status:git('status','--porcelain=v1','--untracked-files=all','--ignore-submodules=none'),diff:hash(git('diff','--binary','--no-ext-diff','--no-textconv','HEAD','--')),package:hash(read(ROOT+'/package.json')),lock:hash(read(ROOT+'/package-lock.json'))});}
function put(rel,bytes){const dest=path.join(directory,rel);fs.mkdirSync(path.dirname(dest),{recursive:true,mode:0o700});fs.writeFileSync(dest,bytes,{flag:'wx',mode:0o600});return dest;}
function verify(){for(const [file,h]of inputs)check(hash(fs.readFileSync(file))===h,'Input changed: '+file);for(const file of missing)absent(file);check(state()===before,'Observed checkout changed');}
